const enorm=s=>(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim();
const EIDX={};function eloIdx(){for(const k in EIDX)delete EIDX[k];Object.keys(ELO.r).forEach(k=>EIDX[enorm(k)]=k);}eloIdx();
function eloOf(name){const n=enorm(name);const k=EALIAS[n]||EIDX[n];return k!=null&&ELO.r[k]!=null?ELO.r[k]:null;}
function eloKey(name){const n=enorm(name);return EALIAS[n]||EIDX[n]||null;}
function formX(k){const f=(ELO.f||{})[k];if(!f)return[1,1];const kp=ELO.kp||25;return[(f[0]+kp)/(f[1]+kp),(f[2]+kp)/(f[3]+kp)];}
function eloLam(m){const rh=eloOf(m.h),ra=eloOf(m.a);if(rh==null||ra==null)return null;const dr=rh-ra+(m.neu?0:100);const[ah,dh]=formX(eloKey(m.h)),[aa,da]=formX(eloKey(m.a));
 return[clamp(Math.exp(ELO.a+ELO.b*dr)*ah*da,.15,4.5),clamp(Math.exp(ELO.a-ELO.b*dr)*aa*dh,.12,4)];}
function eloK(t){t=t.toLowerCase();if(t==='fifa world cup')return 60;if(/euro|copa am|african cup of nations|asian cup|gold cup/.test(t)&&!/qualif/.test(t))return 50;if(/qualif|nations league/.test(t))return 40;if(t==='friendly')return 20;return 30;}
async function updateElo(){const st=LS.get('mb_elo2_t',0);if(Date.now()-st<7*864e5)return;LS.set('mb_elo2_t',Date.now());
 try{const r=await fetch('https://raw.githubusercontent.com/martj42/international_results/master/results.csv');if(!r.ok)return;const txt=await r.text();const R=Object.assign({},ELO.r);const F=JSON.parse(JSON.stringify(ELO.f||{}));const DEC=ELO.dec||.9;let upto=ELO.upto,n=0;
  txt.split('\n').forEach(line=>{const c=line.split(',');if(c.length<9||c[0]<=ELO.upto||c[0]==='date')return;const hs=+c[3],as=+c[4];if(c[3]===''||isNaN(hs)||isNaN(as))return;const h=c[1],a=c[2];R[h]=R[h]??1500;R[a]=R[a]??1500;
   const dr=R[h]-R[a]+(c[8].trim()==='TRUE'?0:100),lh0=Math.exp(ELO.a+ELO.b*dr),la0=Math.exp(ELO.a-ELO.b*dr);[[h,hs,lh0,as,la0],[a,as,la0,hs,lh0]].forEach(([tm,gf,xf,ga,xa])=>{const f=F[tm]||(F[tm]=[0,0,0,0]);f[0]=f[0]*DEC+gf;f[1]=f[1]*DEC+xf;f[2]=f[2]*DEC+ga;f[3]=f[3]*DEC+xa;});const We=1/(Math.pow(10,-dr/400)+1),W=hs>as?1:hs===as?.5:0,gd=Math.abs(hs-as),G=gd<=1?1:gd===2?1.5:(11+gd)/8,d=eloK(c[5])*G*(W-We);R[h]=Math.round((R[h]+d)*10)/10;R[a]=Math.round((R[a]-d)*10)/10;if(c[0]>upto)upto=c[0];n++;});
  if(n){ELO=Object.assign({},ELO,{r:R,f:F,upto});LS.set('mb_elo2',{r:R,f:F,upto});eloIdx();}}catch(e){}}
function mkMatch(e,lg){const c=e.competitions[0],H=c.competitors.find(x=>x.homeAway==='home'),A=c.competitors.find(x=>x.homeAway==='away');
 const m={eid:e.id,lg,hA:H.team.abbreviation,aA:A.team.abbreviation,h:H.team.displayName,a:A.team.displayName,tid:[H.team.id,A.team.id],col:[H.team.color||'7f93ab',H.team.alternateColor||'ffffff',A.team.color||'3df5ff',A.team.alternateColor||'ffffff'],logo:[H.team.logo,A.team.logo],
  c:(DATA.lgm[lg]||{c:[5.1,4.5]}).c,y:(DATA.lgm[lg]||{y:[1.8,2.0]}).y,o:[1.7,1.6],r:[.05,.06],lam:[1.45,1.15],odds:{},dyn:1,neu:!!c.neutralSite};const EL=eloLam(m);if(EL){m.lam=EL;m.lamModel=EL;m.src='team strength ratings (Elo)';}m.g=gridOf(m.lam[0],m.lam[1]);byE[m.eid]=m;lim(()=>enrich(m)).catch(()=>{});return m;}
const am=x=>x==null||x===''?null:(+x>0?1+x/100:1+100/(-x));

// ---- our own model: built from each team's last 5 results (free, no key) ----
function formModel(m,sm){try{const L5=((sm&&sm.boxscore)||{}).lastFiveGames||[];if(L5.length<2)return null;const mu=1.3,k=4;
 const r=L5.map(x=>{const tid=String(x.team&&x.team.id);let gf=0,ga=0,n=0;(x.events||[]).forEach(e=>{const h=+e.homeTeamScore,a=+e.awayTeamScore;if(e.homeTeamScore==null||isNaN(h)||isNaN(a))return;const home=String(e.homeTeamId)===tid;gf+=home?h:a;ga+=home?a:h;n++;});return{tid,att:(gf+k*mu)/(n+k)/mu,def:(ga+k*mu)/(n+k)/mu,n};});
 const tids=(m.tid||[]).map(String);const H=r.find(x=>x.tid===tids[0])||r[0],A=r.find(x=>x.tid===tids[1])||r[1];if(!H||!A||H.n+A.n<3)return null;
 return[clamp(mu*1.1*H.att*A.def,.25,3.6),clamp(mu*.92*A.att*H.def,.2,3.2)];}catch(e){return null;}}
function applyOwnModel(m,sm){if(m.enh)return;const F=eloLam(m)||formModel(m,sm);const isElo=!!eloLam(m);const L=m.odds?priorFrom(m.odds):null;let lam=null;
 if(L&&F){lam=[.85*L[0]+.15*F[0],.85*L[1]+.15*F[1]];m.src=isElo?'bookmaker prices + team ratings':'bookmaker prices + recent form';}else if(L){lam=L;m.src='bookmaker prices';}else if(F){lam=F;m.src=isElo?'team strength ratings (Elo)':'recent form (last 5 games)';}
 if(F)m.lamModel=F;if(!lam)return;m.lam=lam;m.g=gridOf(lam[0],lam[1]);const sh=lam[0]/(lam[0]+lam[1]),lg=DATA.lgm[m.lg]||{c:[5.1,4.5],y:[1.8,2.0]};const tc=lg.c[0]+lg.c[1],ty=lg.y[0]+lg.y[1];
 m.c=[+(tc*(.5+.6*(sh-.5))).toFixed(2),+(tc*(.5-.6*(sh-.5))).toFixed(2)];m.y=[+(ty*(.5-.3*(sh-.5))).toFixed(2),+(ty*(.5+.3*(sh-.5))).toFixed(2)];}
function setOddsKey(k){ODDS_KEY=(k||'').trim();try{ODDS_KEY?localStorage.setItem('mb_okey',ODDS_KEY):localStorage.removeItem('mb_okey')}catch(e){}emit();}
const hasOddsKey=()=>!!ODDS_KEY;
function exportCode(){const o={v:1,t:MY.filter(x=>!x.preset),h:HID,l:LOG,b:BANK};return btoa(unescape(encodeURIComponent(JSON.stringify(o))));}
function importCode(s){const o=JSON.parse(decodeURIComponent(escape(atob(String(s).trim()))));if(!o||o.v!==1)throw new Error('bad');let n=0;
 (o.t||[]).forEach(t=>{if(!MY.some(x=>x.id===t.id)){MY.push(t);n++;}});(o.h||[]).forEach(id=>{if(!HID.includes(id))HID.push(id);});MY=MY.filter(x=>!(x.preset&&HID.includes(x.id)));
 if(Array.isArray(o.l)&&o.l.length>LOG.length)LOG=o.l;LS.set('mb_log',LOG);LS.set('mb_hidden',HID);saveTickets();emit();return n;}
async function enrich(m){const sm=await J(BASE(m.lg)+'summary?event='+m.eid,120000);const p=(sm.pickcenter||[])[0];if(p){const o={H:am(p.homeTeamOdds&&p.homeTeamOdds.moneyLine),D:am(p.drawOdds&&p.drawOdds.moneyLine),A:am(p.awayTeamOdds&&p.awayTeamOdds.moneyLine)};
 if(p.overUnder===2.5&&p.overOdds&&p.underOdds){o['O2.5']=am(p.overOdds);o['U2.5']=am(p.underOdds);}if(o.H&&o.D&&o.A){m.odds=o;recordOdds(m.eid,o,'espn');}}
 applyOwnModel(m,sm);
 delete SIMS[m.eid];if(m.eid===SEL)drawAll();}

