const ACC=LS.get('mb_acc',{});
function gridHDA(m){const g=m.g;let H=0,D=0,A=0,O=0,T=0;for(let i=0;i<9;i++)for(let j=0;j<9;j++){const p=g[i*9+j]||0;T+=p;if(i>j)H+=p;else if(i===j)D+=p;else A+=p;if(i+j>2)O+=p;}return[H/T,D/T,A/T,O/T];}
function trackAcc(eid,s){const m=byE[eid];if(!m||!m.g)return;const a=ACC[eid];
 if(s.state==='pre'){const[h,d,aw,o]=gridHDA(m);ACC[eid]={p:[+h.toFixed(3),+d.toFixed(3),+aw.toFixed(3)],o:+o.toFixed(3),n:m.h+' v '+m.a,t:s.date||null,src:m.src||'bookmaker prices'};}
 else if(s.state==='post'&&a&&!a.out){a.out=[s.h,s.a];}else return;const ks=Object.keys(ACC);if(ks.length>600)ks.slice(0,ks.length-600).forEach(k=>delete ACC[k]);LS.set('mb_acc',ACC);}
