 if(!started){const edge=E!=null&&odds?E-1:null;const k=edge!=null&&edge>0&&odds>1?Math.min(.05,.25*edge/(odds-1))*BANK:0;return{cls:'pre',big:'NOT STARTED',txt:''};}
